  let list = ids
  let tasks = []
  while (list.length) {
    tasks.push(list.slice(0, 100))
    if (list.length < 100) break
    list = list.slice(100)
  }
  let url = 'https://c.musicapp.migu.cn/MIGUM2.0/v1.0/content/resourceinfo.do?resourceType=2'
